window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes"]={"block":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","label":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","count":80,"questions":[{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-cac341c73fd91f11","number":"1001i","sourceNumber":"1001i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Paciente do gênero masculino, 48 anos, casado, tratorista. Vem para atendimento em unidade básica de saúde devido mal-estar, hiporexia, febre não aferida e perda de 3kg (Pesava 90kg). Refere que os sintomas começaram há 4 semanas. Exame físico: BEG, anictérico, descorado 1+/4+. Presença de linfonodomegalia em região cervical anterior a esquerda, de 3,0cm, outro em região supraclavicular esquerda com 3,0cm e um linfonodo de 3,0cm em região inguinal direita. Qual a melhor conduta?","options":{"A":"Amoxacilina/clavulanato por 7 dias e reavaliar após 4 semanas","B":"Encaminhar para biópsia excisional do linfonodo supraclavicular a esquerda","C":"Prednisona 40mg por 10 dias e reavaliar biopsia por agulha fina do linfonodo inguinal","D":"Reavaliar em 3 semanas e se persistência realizar Core Biopsy do linfonodo cervical"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Gânglios aumentados em mais de um lugar do corpo, febre, perda de peso — sinais de alerta que pedem investigação de doença mais séria (como linfoma). Entre os gânglios encontrados, o supraclavicular é o que tem maior chance de esconder uma doença grave, por isso ele é o escolhido pra biópsia excisional (retirar o gânglio inteiro, não só uma amostra pequena), garantindo material suficiente pra um diagnóstico preciso.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352483","ankiGuid":"LO=-DyHY5|"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-d228606a53793252","number":"1002i","sourceNumber":"1002i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Assinale a alternativa que apresenta alterações que podem ser provocadas pela leucemia linfocítica crônica.","options":{"A":"Anemia com presença de linfoblastos","B":"Hipogamaglobulinemia e plaquetopenia","C":"Coombs direto positivo e trombocitopenia","D":"Presença de restos celulares e linfopenia","E":"Pico monoclonal e leucocitose com desvio à esquerda escalonado"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Na leucemia linfocítica crônica (LLC), o sistema imune fica bagunçado: o corpo produz menos anticorpos de verdade (hipogamaglobulinemia, deixando o paciente mais vulnerável a infecções) e a medula, ocupada pelas células doentes, também pode ter dificuldade de produzir plaquetas suficientes (plaquetopenia).","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352484","ankiGuid":"FW;Rwi9gC%"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-2e29059631900337","number":"1003i","sourceNumber":"1003i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Homem, 82 anos de idade, assintomático, apresenta hemograma com 154.000 linfócitos maduros/mm³, Hb de 11,2 g/dL (padrão normocítico e normocrômico) e 210.000 plaquetas/mm³. Exame físico sem alterações. Qual é a hipótese diagnóstica mais provável e a conduta mais adequada para confirmá-la?","options":{"A":"Linfoma linfocítico agudo; imunofenotipagem de sangue periférico","B":"Leucemia linfocítica aguda; PET-TC oncológico e cariótipo de medula óssea","C":"Leucemia linfocítica crônica agudizada; mielograma","D":"Leucemia linfocítica crônica; imunofenotipagem de sangue periférico"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Idoso sem sintomas, com muitos linfócitos MADUROS no sangue (não células jovens/blásticas) — é o retrato clássico da leucemia linfocítica crônica (LLC), uma doença que costuma progredir bem devagar. O exame que confirma o diagnóstico é a imunofenotipagem do sangue periférico, que identifica os marcadores específicos dessas células.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352485","ankiGuid":"DK2E;57.8C"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-62bd1deb2fe073aa","number":"1004i","sourceNumber":"1004i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Adolescente de 14 anos, com história de linfonodomegalia há 3 meses, em região de pescoço e de crescimento progressivo, associada a febre e perda de 15% de seu peso. Exame físico: linfonodos palpáveis em região cervical baixa e supraclavicular com cerca de 5 cm de diâmetro, indolor a palpação e endurecido. A conduta adequada é:","options":{"A":"Antibioticoterapia e seguimento clínico","B":"Observação clínica e reavaliação em 15 dias","C":"Biópsia excisional do linfonodo e estudo histopatológico","D":"Hemograma e biópsia de medula óssea"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Gânglio que cresce sem parar por meses, endurecido, sem dor, junto com febre e perda de peso importante num adolescente — sinais de alarme que pedem biópsia excisional (retirada completa do gânglio) pra estudo detalhado, e não só observação ou tratamento com antibiótico.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352486","ankiGuid":"yoXh(y4F`;"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-be7ecee8860de8af","number":"1005i","sourceNumber":"1005i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Um paciente de 5 anos, assintomático, está em consulta de puericultura. Ao exame físico, é identificado um linfonodo supraclavicular palpável. Nesse caso, está indicada a biópsia desse linfonodo?","options":{"A":"Não, pois o paciente deve ser revisado em duas semanas para avaliar se houve regressão","B":"Não, pois o paciente é assintomático","C":"Sim, independentemente das características do linfonodo","D":"Sim, se o linfonodo for firmemente aderido e maior que 2 cm","E":"Sim, se o linfonodo for maior que 1 cm"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Um gânglio na região supraclavicular (acima da clavícula) numa criança, mesmo sem nenhum sintoma, já é considerado um sinal de alerta importante — essa localização específica tem uma chance bem maior de esconder uma doença grave (como linfoma), por isso a biópsia é indicada independente de como o gânglio se apresenta ao exame.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352487","ankiGuid":"Bl5[q?NpSQ"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-b6839ee14632799c","number":"1006i","sourceNumber":"1006i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Assinalar a alternativa que preenche as lacunas abaixo CORRETAMENTE: A reação leucemoide é definida pela leucometria maior que _______ leucócitos/mm³, associada ao aumento no número de células _______ imaturas. Deve ser diferenciada da leucemia mieloide crônica ou da leucemia mieloide juvenil. Dentre as principais causas de reação leucemoide estão as infecções piogênicas, as doenças inflamatórias, a insuficiência hepática, a acidose diabética e a síndrome de _______ (doença mieloproliferativa transitória).","options":{"A":"50.000 l linfoides l DiGeorge","B":"100.000 l linfoides l Down","C":"50.000 l mieloides l Down","D":"100.000 l mieloides l DiGeorge"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"A reação leucemoide é definida como leucócitos acima de 50.000/mm³, com aumento de células MIELOIDES imaturas (não linfoides) — geralmente uma resposta exagerada do corpo a uma infecção ou inflamação grave, não uma leucemia de verdade. Uma causa específica dessa reação em bebês com síndrome de Down é uma condição temporária chamada doença mieloproliferativa transitória.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352488","ankiGuid":"w@oRfjGa]|"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-b51579598932cd5b","number":"1007i","sourceNumber":"1007i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Distinguir um linfonodo inflamatório de um neoplásico pode ser um desafio para o pediatra. Qual das situações a seguir sugere benignidade, sem necessidade de investigação?","options":{"A":"Ausência de linfonodos palpáveis em recém-nascidos","B":"Nódulo linfático maior que 1 cm, em dois locais anatômicos","C":"Linfonodo epitroclear com 0,7 cm","D":"Linfonodo inguinal com 2 cm","E":"Linfonodomegalia localizada, com febre por mais de 7 dias"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"A situação mais tranquilizadora entre as opções é simplesmente não ter nenhum gânglio palpável num recém-nascido — isso é normal e não precisa de investigação nenhuma. As outras situações descritas (gânglio grande, em mais de um lugar, febre prolongada) são todas sinais de alerta que pedem atenção.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352489","ankiGuid":"y}mjcVW.s>"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-4e970c878ecf1f82","number":"1008i","sourceNumber":"1008i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Os exames laboratoriais são fundamentais no diagnóstico e no estadiamento dos linfomas não Hodgkin. Em relação ao tema, assinale a alternativa correta.","options":{"A":"O hemograma está sempre alterado","B":"A velocidade de hemossedimentação, muito específica, costuma estar aumentada","C":"A desidrogenase lática está tão mais elevada quanto a quantidade de células tumorais e a intensidade de apoptose e, quanto mais elevada, pior o prognóstico","D":"Mielograma, para avaliar a infiltração medular, deve ser feito em um único ponto e deve ser avaliado somente através do exame microscópico direto","E":"A imunofenotipagem não está indicada para a maioria dos pacientes"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Na investigação dos linfomas não Hodgkin, a LDH (desidrogenase lática) é um exame importante: quanto mais alta ela está, mais células tumorais estão se multiplicando e morrendo rápido (apoptose), e isso costuma indicar um prognóstico pior — por isso ela entra em vários índices usados pra avaliar a gravidade da doença.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352490","ankiGuid":"Gu8@s7q3x{"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-6ed500b4d5c5328f","number":"1009i","sourceNumber":"1009i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Jovem, 17 anos de idade, procurou atendimento devido a abaulamento na região cervical há 6 meses, com crescimento progressivo no período. Refere ainda episódios de febre diária, sudorese e emagrecimento no último mês. Nega outros antecedentes ou hábitos e vícios. Qual é a principal hipótese diagnóstica e a conduta para o caso?","options":{"A":"Carcinoma de tireoide; tireoidectomia total com linfadenectomia cervical","B":"Nódulo reacional; seguimento clínico, com retorno em 6 meses","C":"Linfoma; biópsia do linfonodo cervical","D":"Carcinoma espinocelular de cabeça e pescoço; biópsia com agulha grossa guiada por ultrassonografia"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Massa no pescoço crescendo por meses, febre diária, suor noturno e emagrecimento num jovem — sinais clássicos de linfoma. A conduta certa é a biópsia do linfonodo cervical, que confirma o diagnóstico e mostra o tipo exato da doença.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352491","ankiGuid":"d-)5OZX=sv"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-5307bf91961cdf63","number":"1010i","sourceNumber":"1010i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Assinale a alternativa correta sobre o linfoma de Hodgkin.","options":{"A":"O subtipo de celularidade mista é o mais comum","B":"A apresentação infradiafragmática exclusiva implica em pior prognóstico","C":"A ressonância nuclear magnética é considerada o exame padrão ouro para o diagnóstico inicial","D":"Idade inferior a 45 anos e níveis de hemoglobina inferiores a 10 g/dl são fatores de pior prognóstico"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Quando o linfoma de Hodgkin aparece SÓ abaixo do diafragma (sem envolver os gânglios do tórax/pescoço, um padrão bem menos comum), isso é considerado um sinal de pior prognóstico, já que a doença costuma seguir um padrão mais previsível de disseminação por contiguidade, começando geralmente acima do diafragma.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352492","ankiGuid":"p~=-^SU$GB"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-9b4ae4e8047562e1","number":"1011i","sourceNumber":"1011i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Homem de 58 anos com febre há 4 dias foi internado para tratamento de extensa celulite em membro inferior esquerdo associada a úlcera plantar infectada. AP: obeso e diabético mal controlado. Hemograma: Glóbulos vermelhos: 3 840 000/mm³, Hemoglobina: 11,3 g/dL, Hematócrito: 35,2%, VCM: 87 fL, HCM: 33 pg, Plaquetas: 580000/mm³, Glóbulos brancos: 46000/mm³ (mielócitos: 3%, metamielócitos: 6%, bastões: 12%, neutrófilos: 58%, basófilos: 0%, eosinófilos: 3%, linfócitos: 8% monócitos: 10%), RDW: 16%, Reticulócitos: 1,3%. A hipótese diagnóstica e a conduta são:","options":{"A":"Leucemia mieloide aguda; coleta de medula óssea","B":"Leucemia mieloide crônica; coleta de medula óssea e pesquisa de cromossomo Filadélfia","C":"Reação leucemoide associada a plaquetose reacional; antibioticoterapia","D":"Quadro reacional sobreposto a leucemia mieloide aguda; antibioticoterapia e coleta de medula óssea"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Diabético com uma infecção grave na perna (celulite com úlcera infectada) — o corpo reage com um aumento importante dos leucócitos (46.000!), incluindo formas jovens (mielócitos, metamielócitos, bastões), mas SEM blastos (células muito imaturas que indicariam leucemia de verdade), e as plaquetas também sobem (reação, não doença da medula). É uma reação leucemoide — o corpo 'gritando' de tanta infecção — e o tratamento é simplesmente cuidar da infecção com antibiótico.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352493","ankiGuid":"c~9sjxqv9("},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-668b9b32762925d3","number":"1012i","sourceNumber":"1012i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Adolescente de 15 anos de idade, apresenta adenomegalia cervical unilateral há 6 meses e com crescimento progressivo; nos últimos 2 meses cursa com febre diária, perda de peso e sudorese. Qual diagnóstico mais provável?","options":{"A":"Linfoma de Burkitt","B":"Neuroblastoma","C":"Carcinoma de tireoide","D":"Linfoma de Hodgkin","E":"Carcinoma de glândulas salivares"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Gânglio no pescoço de um lado só, crescendo por meses, com febre diária, perda de peso e suor noturno num adolescente — quadro clássico de linfoma de Hodgkin.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352494","ankiGuid":"D1{w.5MvKl"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-7a3f8f59758b9ad5","number":"1013i","sourceNumber":"1013i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Mulher de 43 anos se apresenta ao pronto-socorro com história de desconforto abdominal progressivo e ganho de peso há três semanas. Ela relata não possuir doenças pregressas e não faz uso de medicamentos. No exame físico, nota-se uma face pletórica. O abdômen está tenso, sensível e moderadamente distendido. Os achados laboratoriais demonstram hemoglobina de 18,7 g/dL, contagem de leucócitos de 9000/µL, contagem de plaquetas de 401.000/µL, nível de alanina aminotransferase (ALT) de 84 U/L, aspartato aminotransferase (AST) de 107 U/L e nível de bilirrubina total de 0,9 mg/dL. O teste sérico de gravidez é negativo. A ultrassonografia abdominal com doppler demonstra trombose da veia hepática. Qual dos seguintes testes de diagnóstico tem mais probabilidade de estabelecer a causa da apresentação clínica da paciente?","options":{"A":"Pesquisa da mutação JAK2V617F","B":"Pesquisa de trombofilias hereditárias","C":"Tomografia computadorizada (TC) helicoidal do abdômen","D":"Citometria de fluxo para expressão de CD55 e CD59"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Cara vermelha (pletórica), barriga inchada e dolorida, hemoglobina bem alta (18,7!) e trombose de uma veia grande do fígado (veia hepática, causando a síndrome de Budd-Chiari) — essa combinação é bem característica da policitemia vera, uma doença em que a medula produz sangue demais, deixando-o mais 'grosso' e propenso a formar coágulos em lugares incomuns. O exame que confirma é a pesquisa da mutação JAK2, presente na maioria dos casos dessa doença.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352495","ankiGuid":"mF-j=+SIlM"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-afa2097da99b2e82","number":"1014i","sourceNumber":"1014i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Correlacione o carcinógeno suspeito à neoplasia: I - Helicobacter pylori; II - Vírus HIV; III - Vírus HTLV-1; IV - Vírus Epstein Barr; V - vírus HTLV-2; a - Leucemia de célula T adulta; b - Linfoma de Burkitt; c - Linfoma Gátrico MALT; d - Sarcoma de Kaposi; e - Tricoleucemia; Marque a opção mais adequada:","options":{"A":"I-c, II-e, III-a, IV-c, V-b","B":"I-d, II-a, III-b, IV-e, V-c","C":"I-c, II-d, III-a, IV-b, V-e","D":"I-c, II-a, III-b, IV-d, V-e","E":"I-c, II-d, III-e, IV-b, V-a"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"É uma questão de decorar as associações clássicas: H. pylori causa o linfoma MALT gástrico (a bactéria fica no estômago, irritando cronicamente o tecido linfoide da mucosa); HIV está ligado ao sarcoma de Kaposi (por deixar o corpo vulnerável ao HHV8, o verdadeiro causador); HTLV-1 causa a leucemia de células T do adulto; Epstein-Barr causa o linfoma de Burkitt; e o HTLV-2 tem associação descrita com a tricoleucemia.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352496","ankiGuid":"KPjy*uJx;?"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-09f7ca247c542c25","number":"1015i","sourceNumber":"1015i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"A leucemia mieloide crônica (LMC) é uma doença mieloproliferativa caracterizada pelo acúmulo excessivo de células mieloides de aparência normal. Qual item se mostra incorreto?","options":{"A":"Ela ocorre com uma incidência anual de 1,0 a 1,5/100.000 habitantes, afetando principalmente adultos, entre 50 e 55 anos","B":"E casuísticas brasileiras indicam que a mediana de idade na apresentação da doença é, no mínimo, dez anos mais elevada que a encontrada na literatura internacional, com mediana de idade ao diagnóstico entre 40 e 46 anos","C":"Os sintomas iniciais possam incluir letargia, perda de peso, sangramento anormal, suores, anemia ou esplenomegalia","D":"Em países mais desenvolvidos, 50% dos pacientes são assintomáticos e são diagnosticados como consequência de exames de sangue realizados por motivos não relacionados"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"A frase errada é a B: se a média de idade no Brasil (40-46 anos) é dita como 'dez anos mais elevada' que a literatura internacional, isso não bate — na verdade, a idade citada é MENOR do que a média internacional (que gira em torno de 50-55 anos, como a própria alternativa A afirma), não maior. É uma contradição interna na frase. As outras alternativas (incidência anual, sintomas iniciais, e boa parte assintomática ao diagnóstico) estão corretas.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352497","ankiGuid":"c#w&ncf%/V"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-bf90926f9a2e0ff0","number":"1016i","sourceNumber":"1016i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Paciente masculino, 32 anos de idade, procurou atendimento médico. Há três meses com astenia e emagrecimento, febre intermitente, icterícia e aumento do volume da região cervical direita (D). Ao exame físico, os achados são: ictérico++, hipocorado++, hepatoesplenomegalia, massa na região submandibular D de limites mal definidos e consistência endurecida. Palpam-se linfonodos aumentados nas cadeias axilares e inguinais, bilateralmente. Nega histórico de doença pessoal ou familiar, além do uso de drogas ou álcool. Laboratório inicial: Hb = 10.4 g/dl; leucócitos = 4.680/mm³; plaquetas = 52.000/mm³; bilT = 13.7 mg/dl; biD = 10.6 mg/dl; TGO = 116 UI/l; TGP = 157 UI/l; FA = 1.289 UI/l; GGT = 1.456 UI/l; albumina = 2.8 g/dl; LDH = 1.350 UI/l. Solicitado teste rápido para HIV, com resultado positivo. O diagnóstico mais provável para o caso acima é:","options":{"A":"Linfoma de Hodgkin","B":"Tricoleucemia (Hairy Cell Leukemia)","C":"Linfoma não Hodgkin","D":"Tuberculose extrapulmonar"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Cansaço, emagrecimento, febre, icterícia, massa no pescoço, fígado e baço aumentados, gânglios espalhados pelo corpo, e um HIV que deu positivo — esse conjunto (principalmente a imunossupressão pelo HIV) é um forte indicativo de linfoma não Hodgkin, que é mais agressivo e mais comum em pacientes imunossuprimidos.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352498","ankiGuid":"lRVwdEi,Qi"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-1d2d113f2e9756cd","number":"1017i","sourceNumber":"1017i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Paciente, 66 anos, previamente hígido e assintomático, realizou check up com hemograma apresentando tais valores Hb: 14, Ht: 42%; VCM 86, leucócitos: 98.000, segmentados: 7800, linfócitos: 86.000, plaquetas: 166.000. Exame físico normal. Esfregaço de sangue periférico evidenciou linfócitos maduros, confirmados posteriormente com imunofenotipagem de sangue periférico. Sobre o caso, assinale a alternativa CORRETA.","options":{"A":"Trata-se de uma provável leucemia mieloide crônica (LMC), e seu tratamento deverá ser feito com quimioterapia","B":"Trata-se de uma provável leucemia linfoide crônica (LLC), e a conduta deverá ser expectante","C":"Trata-se de uma provável leucemia mieloide crônica (LMC), e o ESP poderá evidenciar manchas de Grumprecht","D":"Trata-se de uma provável leucemia linfoide crônica (LLC), e esse paciente terá sobrevida menor do que 2 anos","E":"Trata-se de uma provável leucemia mieloide crônica (LMC), e a conduta deverá ser expectante"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Idoso sem sintomas, achado por acaso num exame de rotina, com muitos linfócitos MADUROS no sangue e exame físico normal — é o retrato clássico de uma leucemia linfoide crônica (LLC) descoberta bem cedo. Como a doença costuma evoluir devagar e ele não tem nenhum sintoma, a conduta correta é apenas observar (conduta expectante), sem começar tratamento ainda.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352499","ankiGuid":"OG|mWQ36nU"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-a7138c63b045999c","number":"1018i","sourceNumber":"1018i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Homem com 58 anos apresenta anemia, esplenomegalia, leucocitose com basofilia, hiperuricemia, fosfatase alcalina dos leucócitos diminuída com cromossomo Philadelphia positivo e hipercelularidade granulocítica da medula óssea. Assinale a alternativa que apresenta o diagnóstico:","options":{"A":"Leucemia mieloide crônica","B":"Leucemia linfoide crônica","C":"Leucemia mieloblástica aguda","D":"Leucemia linfoblástica aguda"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Anemia, baço aumentado, leucócitos altos com basófilos aumentados, ácido úrico alto (muitas células se renovando), a enzima fosfatase alcalina dos leucócitos BAIXA (um detalhe clássico que ajuda a diferenciar de uma reação leucemoide, onde ela estaria alta), e o cromossomo Philadelphia positivo — tudo isso fecha o diagnóstico de leucemia mieloide crônica.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352500","ankiGuid":"B,*0RGNC(q"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-89deef6292feabbd","number":"1019i","sourceNumber":"1019i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Homem, 48 anos, retorna a consulta ambulatorial para resultado de exames após acidente vascular cerebral isquêmico há 4 semanas, com boa evolução da fase aguda. Antecedente pessoal: cirurgia bariátrica há 5 anos, sem acompanhamento ou medicações regulares. Hemoglobina= 19 g/dL, VCM= 63fL, hemácias= 7.000.000/µL; leucócitos= 18.000/µL (segmentados 76%, linfócitos 10%, monócitos 5%; eosinófilos 6%, basófilos 3%), plaquetas= 550.000/µL. Ferritina: 4ng/mL. Exame físico: baço palpável a 2 cm do rebordo costal esquerdo. O DIAGNÓSTICO É:","options":{"A":"Traço talassêmico","B":"Anemia ferropriva","C":"Policitemia Vera","D":"Trombofilia hereditária"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Homem com AVC recente, hemoglobina MUITO alta (19!) com MUITAS hemácias (7 milhões), leucócitos e plaquetas também altos, ferritina baixíssima (o corpo 'gastou' o ferro fabricando tanto sangue), e baço palpável — é o quadro clássico de policitemia vera, uma doença que deixa o sangue mais 'grosso' e aumenta bastante o risco de trombose (como o AVC que ele já teve).","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352501","ankiGuid":"r/7n5NOv>)"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-c8316991166ef2bf","number":"1020i","sourceNumber":"1020i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Vanda, 66 anos, foi encaminhada ao ambulatório de Hematologia do Hospital Universitário para investigação diagnóstica de pancitopenia. Em consulta, a paciente refere astenia progressiva nos últimos 3 meses e relata também que passou a apresentar, há 2 semanas, petéquias e gengivorragia. Diante disso, procurou atendimento médico, quando foi realizado hemograma completo que revelou anemia normocítica normocrômica, com baixa contagem de reticulócitos, leucopenia com diferencial normal e plaquetopenia. Um exame hematoscópico revelou presença de elevada porcentagem de dacriócitos (hemácias “em lágrima”). Nessa situação, o diagnóstico mais provável da paciente e o exame complementar a ser solicitado para sua confirmação devem ser, respectivamente,","options":{"A":"Mielofibrose e biópsia de medula óssea","B":"Leucemia mieloide aguda e aspirado de medula óssea","C":"Mielodisplasia e citometria de fluxo de sangue periférico","D":"Aplasia de medula óssea e sorologia para parvovírus B19"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Cansaço progressivo, petéquias e sangramento de gengiva, pancitopenia (todas as três linhagens do sangue baixas) com reticulócitos baixos (a medula não compensando), e a presença de muitos dacriócitos (hemácias em formato de gota) no esfregaço — esse achado é bem característico da mielofibrose, uma doença em que a medula óssea vai sendo substituída por fibrose, 'espremendo' as células jovens pra fora, deformando-as em formato de gota. O exame que confirma é a biópsia de medula óssea (o aspirado costuma vir 'seco', sem material suficiente, por causa da fibrose).","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352502","ankiGuid":"P=sMYC]suu"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-09a6d29a1ba8b8e9","number":"1021i","sourceNumber":"1021i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Um paciente de 60 anos, não tabagista, apresenta hemoglobina de 20g/dL, microcitose, níveis baixos de eritropoietina, prurido cutâneo intenso após banhos quentes e cefaleia diária. O diagnóstico é","options":{"A":"Policitemia do DPOC","B":"Mieloma múltiplo","C":"Uso de anabolizantes esteroides","D":"Policitemia vera","E":"Mielodisplasia"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Hemoglobina bem alta (20!), eritropoietina BAIXA (mostrando que não é o corpo tentando compensar uma falta de oxigênio, e sim a própria medula produzindo demais por conta própria), coceira depois de banho quente (um sintoma bem característico!) e dor de cabeça diária — tudo aponta pra policitemia vera.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352503","ankiGuid":"AlvY2{zeZz"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-20b3582a3a6a6802","number":"1022i","sourceNumber":"1022i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Uma mulher encontra-se em tratamento para Linfoma Não Hodgkin. São agentes infecciosos que podem ter deflagrado a doença:","options":{"A":"HBV, Bartonella henselae, Helicobacter pylori, HSV","B":"Campylobacter jejuni, EBV, Sporothrix schenckii","C":"CMV, Varicela Zoster, HBV","D":"HHV8, HCV, HTLV1","E":"Yersinia enterocolítica, Chlamydia pneumoniae, HCV"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Alguns vírus são conhecidos por poderem desencadear linfomas não Hodgkin: o HHV8 (ligado ao sarcoma de Kaposi e a alguns linfomas), o vírus da hepatite C (ligado ao linfoma de zona marginal) e o HTLV1 (ligado à leucemia/linfoma de células T do adulto).","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352504","ankiGuid":"DUl-QD[4X0"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-1ad4839f177f4824","number":"1023i","sourceNumber":"1023i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Sobre os linfomas não Hodgkin indolentes, assinale a alternativa INCORRETA:","options":{"A":"Apresentam sobrevida prolongada (acima de 5 anos)","B":"Acometem indivíduos idosos","C":"Possuem alto potencial de cura","D":"Se apresentam com estágio avançado ao diagnóstico","E":"A presença de citopenia ou sintomas B são algumas indicações para início do tratamento"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"A frase errada é a C: os linfomas não Hodgkin indolentes (de crescimento lento) costumam ter sobrevida longa, mas justamente por crescerem devagar, geralmente NÃO têm um alto potencial de cura — é o oposto do que se vê nos linfomas agressivos, que crescem rápido mas, paradoxalmente, respondem melhor à quimioterapia intensiva e têm mais chance de cura. As outras frases (sobre sobrevida longa, acometer idosos, apresentação em estágio avançado, e indicações de tratamento) estão corretas.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352505","ankiGuid":"ik9XL,jJs("},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-0fbf9b6c75802289","number":"1024i","sourceNumber":"1024i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Paciente de 62 anos de idade, do sexo feminino procura seu atendimento por alteração do hemograma. Apresenta hemograma de quatro meses antes e atual com leucocitose às custas de linfócitos (9.000/mm³). Nega perda ponderal, nega febre, nega outros sintomas associados. Você solicitou TC de tórax, abdome e pelve que não demonstrou linfadenopatia ou hepatoesplenomegalia. Considerando o diagnóstico mais provável, analise as assertivas. I. O paciente tem indicação de tratamento com rituximabe, fludarabina ciclofosfamida. II. O acometimento da medula óssea ocorre apenas na menor parte dos casos. III. O quadro pode estar associado a trombocitopenia autoimune. IV. A doença é rara em crianças. Estão corretas somente as assertivas","options":{"A":"I e II","B":"I e III","C":"II e III","D":"II e IV","E":"III e IV"},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"A frase III está certa (a LLC pode vir junto com trombocitopenia autoimune, uma complicação conhecida) e a IV também (é uma doença rara em crianças, típica de adultos mais velhos). Já a I está errada (com esse quadro tão leve e assintomático, sem organomegalia, ainda não há indicação de começar quimioterapia — a conduta seria observar), e a II também está errada (o acometimento da medula óssea acontece na MAIORIA dos casos de LLC, não numa minoria, já que é praticamente parte da definição da doença).","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352506","ankiGuid":"vZn|IsahnX"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-69f3ef2c858a7121","number":"1025i","sourceNumber":"1025i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Os linfomas (Doença de Hodgkin e Linfomas não Hodgkin) constituem um grupo de doenças neoplásicas malignas que se originam de células do sistema imunológico. Somente está errado o item:","options":{"A":"Linfoma Difuso de Grandes Células B (LDGC B) é o mais comum, correspondendo a cerca de 40% dos novos casos diagnosticados e a cerca de 30% de todos os casos de LNH","B":"Linfoma de Burkitt, o LDGC B é dos mais incidentes em indivíduos HIV positivos","C":"Os Linfomas não Hodgkin (LNH) agressivos compreendem um grupo biológica e clinicamente homogêneo de hemopatias malignas","D":"O LDGC B pode-se manifestar nos linfonodos ou sítios extra-nodais, como osso, pele, tireoide, trato gastrointestinal (TGI), sistema nervoso central (SNC) e testículo"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"A frase errada é a C: os linfomas não Hodgkin agressivos, na verdade, formam um grupo bem HETEROGÊNEO (bem diferente entre si), não homogêneo — existem vários subtipos diferentes com comportamentos biológicos distintos. As outras frases (sobre a frequência do linfoma difuso de grandes células B, sua associação com HIV, e os locais onde pode se manifestar) estão corretas.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352507","ankiGuid":"H50g6MJ+!_"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-84eab420c96b0643","number":"1026i","sourceNumber":"1026i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Paciente de 62 anos, sexo masculino, admitido na enfermaria para investigação diagnóstica. Relata perda de peso involuntária de cerca de 18 kg nos últimos 5 meses, sensação de saciedade precoce, hiporexia, fadiga, astenia e febre. Ao exame abdominal percebe-se esplenomegalia (baço Boyd III). Exames laboratoriais: Hb: 10,5 g/dl (VR: 11.3 a 16.3); VCM: 80 fl (VR: 77 a 92); HCM: 28 pg (VR: 27 a 32); CHCM: 32 g/dl; RDW: 22; Global de leucócitos: 590.000/mm³ (VR: 1800 a 7500); Segmentados: 34%; Bastonetes: 24%; Metamielócitos: 13%; Mielócitos: 9%; Promielócitos: 5%; Blastos: 3%; Eosinófilos: 4% Basófilos: 5% Linfócitos: 2% Monócitos: 1%; Plaquetas: 400.000/ml (VR: 130.000 a 370.000/ml). Diante do caso acima, assinale o diagnóstico mais provável:","options":{"A":"Leucemia mieloide crônica","B":"Trombocitemia essencial","C":"Abscesso esplênico","D":"Leucemia linfocítica crônica"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Perda de peso importante, saciedade precoce, cansaço, febre e um baço muito aumentado, com leucócitos extremamente altos (590.000!) mostrando praticamente todas as fases de maturação das células mieloides (de blastos até segmentados) e basofilia — é o retrato clássico da leucemia mieloide crônica, numa fase bem avançada.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352508","ankiGuid":"HgLibY0(_J"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-468728e2ca676042","number":"1027i","sourceNumber":"1027i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"O acometimento primário do sistema nervoso central por linfoma é, mais provavelmente, do tipo:","options":{"A":"Células B","B":"Hodgkin","C":"Kaposi","D":"Células T"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Quando um linfoma aparece primariamente dentro do sistema nervoso central (sem estar em outro lugar do corpo primeiro), o tipo mais provável é de células B — é o tipo predominante desse linfoma raro e específico do cérebro.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352509","ankiGuid":"qpoxo*7A)v"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-56dd60034a65e1d0","number":"1028i","sourceNumber":"1028i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Das doenças a seguir, qual apresenta risco maior de desenvolvimento de linfomas quando comparado à população geral?","options":{"A":"Lúpus eritematoso sistêmico","B":"Doença de Behçet","C":"Síndrome de Sjögren","D":"Policondrite recidivante","E":"Doença mista do tecido conjuntivo"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Entre as doenças autoimunes listadas, a síndrome de Sjögren é a que tem associação mais forte e bem estabelecida com o desenvolvimento de linfoma (principalmente o do tipo MALT, nas glândulas salivares), comparada com a população geral.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352510","ankiGuid":"TA:m@q<M2"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-4eead0577f918db6","number":"1029i","sourceNumber":"1029i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Homem, 79 anos de idade, apresenta linfocitose nos exames de rotina solicitados em consulta com o seu geriatra. Exames laboratoriais: Hb =11,1 g/dL; VCM = 90 fL; Leucócitos = 35.500/mL (32.100/mL linfócitos) e Plaquetas 108.000/mL. Exame físico: linfonodomegalia cervical bilateral e esplenomegalia, com baço a 3 cm do rebordo costal esquerdo. Qual é a hipótese diagnóstica mais provável e a melhor conduta nesse momento?","options":{"A":"Leucemia linfocítica aguda e imunofenotipagem de sangue periférico","B":"Leucemia linfocítica crônica e imunofenotipagem de medula óssea","C":"Leucemia linfocítica crônica e imunofenotipagem de sangue periférico","D":"Linfoma leucemizado e imunofenotipagem de medula óssea","E":"Linfoma leucemizado e biópsia de linfonodo cervical e de medula óssea"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Idoso com muitos linfócitos no sangue, gânglios aumentados nos dois lados do pescoço e baço palpável — quadro sugestivo de leucemia linfocítica crônica. A investigação segue com imunofenotipagem do sangue periférico, que confirma o diagnóstico ao mostrar os marcadores específicos dessas células.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352511","ankiGuid":"dbEh42ecn="},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-442eff0d7a609848","number":"1030i","sourceNumber":"1030i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Homem de 53 anos procura auxílio médico devido à massa cervical não dolorosa, que foi notada há cerca de dois meses. Relata que quando bebe um a dois copos de vinho, a massa cervical se torna dolorosa. Ele também se queixa de febre intermitente, sudorese noturna, prurido e perda de peso superior a 10% do peso corporal habitual, no último mês. Ao exame físico, palpa-se linfonodo de aproximadamente 3 cm na região cervical, à esquerda, de consistência fibro-elástica. Vários outros linfonodos cervicais são também palpáveis à esquerda, assim como um linfonodo na região axilar esquerda. O fígado está aumentado, mas não há esplenomegalia ao exame. Trouxe consigo radiografia de tórax que estava normal. Considerando-se esses dados, qual é o diagnóstico MAIS PROVÁVEL?","options":{"A":"Linfoma de Hodgkin","B":"Mononucleose infecciosa","C":"Sarcoidose","D":"Tricoleucemia"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Massa no pescoço que dói depois de beber álcool — esse é um sinal bem raro, mas bastante específico do linfoma de Hodgkin! Junto com febre, suor noturno, coceira na pele e perda de peso importante, e gânglios firmes e indolores em vários lugares, fecha bem o quadro dessa doença.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352512","ankiGuid":"iKy0,pzXOQ"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-357ac81f8c40fb48","number":"1031i","sourceNumber":"1031i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Paciente de 62 anos veio encaminhado do oftalmologista, pois apresentava o hemograma que segue: Hb = 13,3g/dl Leucócitos = 143.000/mm³ (Mieloblastos 02%, Promielócitos 05%, Mielócitos 09%, Metamielócitos 11%, Bastonetes 15%, Segmentados 34%, Eosinófilos 03%, Basófilos 03%, Linfócitos 10% e Monócitos 08%) e Plaquetas de 650.000/mm³. Ao exame, apresentava apenas o baço palpável a 5 cm do RCE. Qual é a resposta correta?","options":{"A":"Provável Leucemia Mielóide Aguda, sendo necessário mielograma para confirmação, tratamento com quimioterapia sistêmica e plaquetaférese","B":"Trata-se de uma Trombocitemia Essencial, diagnosticada pela pesquisa da mutação da JAK II e o tratamento com AAS e hydroxyureia","C":"Provável Leucemia Mielóide Crônica, sendo o diagnóstico firmado pela pesquisa da mutação BCR/ABL, e o tratamento deve ser com Inibidores da Tirosino quinase","D":"Provável quadro infeccioso, devendo ser pesquisado o foco e o tratamento com antibióticos sistêmicos"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Idoso com leucócitos bem altos (143.000!) mostrando todas as fases de maturação das células mieloides e baço bem aumentado — é o retrato clássico da leucemia mieloide crônica. O diagnóstico é confirmado pela pesquisa da mutação BCR/ABL, e o tratamento hoje é feito com os inibidores da tirosina quinase, remédios que revolucionaram o prognóstico dessa doença.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352513","ankiGuid":"QCH~%nFe[!"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-d0ef26fd46d073ec","number":"1032i","sourceNumber":"1032i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Um paciente de 38 anos apresenta queixas de indisposição e fraqueza há 5 meses. O exame físico revela mucosas levemente hipocoradas, sem demais achados relevantes. Um hemograma é, então, solicitado: Hb 9,6g/dl; VCM 88 fL; Leucócitos 4300/mm³; Neutrófilos 55%; Linfócitos 40%; Eosinófilos 2%; Monócitos 3%; Plaquetas 160.000/mm³. Diante desse quadro de anemia, foram solicitados os seguintes exames: Ferritina 180ng/ml; Creatinina 1,0 mg/dl; Bilirrubinas direta 0,5 mg/dl; Bilirrubinas indiretas 0,3mg/dl; Bilirrubinas totais 0,8mg/dl; Coombs Direto negativo. Eletroforese de hemoglobina: Hb AA 97% com Hb A2 de 2,5%. Diante dos exames acima, um mielograma foi realizado: Medula óssea hipercelular com 55% de diseritropoiese 20% de disgranulopoiese. Podemos afirmar que:","options":{"A":"Trata-se de Síndrome Mielodisplástica pois há mais de 10% de displasia","B":"Não se trata de Síndrome Mielodisplástica pois não há evidências de que a displasia seja monoclonal e o paciente é jovem","C":"O próximo passo seria a realização de colonoscopia","D":"As 3 alternativas acima estão erradas"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Esse é um caso complexo, com achados leves de displasia na medula (que sozinhos não fecham diagnóstico de síndrome mielodisplásica num paciente tão jovem, sem outras evidências de que seja realmente um problema clonal da medula) — nenhuma das três primeiras afirmações isoladas capta bem a situação completa, sendo necessária uma investigação mais aprofundada antes de fechar qualquer diagnóstico definitivo.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352514","ankiGuid":"gcv{VnbV|{"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-db2c1b27574e6b27","number":"1033i","sourceNumber":"1033i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Pacientes com linfomas apresentam sinais e sintomas que são chamados constitucionais. Qual sinal / sintoma abaixo NÃO é considerado constitucional nos linfomas?","options":{"A":"Perda de peso","B":"Febre vespertina","C":"Sudorese noturna","D":"Hepatoesplenomegalia"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Os sintomas constitucionais clássicos dos linfomas (também chamados de 'sintomas B') são febre, sudorese noturna e perda de peso — sintomas gerais do corpo. Já o aumento do fígado e do baço (hepatoesplenomegalia) é um achado do EXAME FÍSICO, não um sintoma constitucional em si — por isso é a exceção certa.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352515","ankiGuid":"f^fe+?3)wx"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-fc79e610ec582ec4","number":"1034i","sourceNumber":"1034i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"O paciente é um homem de 50 anos referindo plenitude pós-prandial mesmo após comer pequenas quantidades. Encontra-se hipocorado, anictérico e baço palpável 8 cm abaixo da reborda costal. O resto do exame físico é normal. Ht = 37%; plaquetas = 377.000/mm³. Contagem de leucócitos com 50.000/mm³, granulócitos = 43%; bastões = 13%; metamielócitos = 18%; mielócitos = 10%; promielócitos = 2%; blastos = 2%; monócitos = 11%; basófilos = 2%, eosinófilos = 2%; linfócitos = 1%. Qual é o diagnóstico mais provável?","options":{"A":"Leucemia mieloide crônica","B":"Leucemia linfocítica crônica","C":"Leucemia mieloide aguda","D":"Anemia megaloblástica"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Sensação de estômago cheio rápido demais (por causa do baço enorme empurrando o estômago), baço bem grande (8cm abaixo da costela!), leucócitos altos (50.000) mostrando todas as fases de maturação das células mieloides — é o retrato clássico da leucemia mieloide crônica.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352516","ankiGuid":"xBwuDYJ&v|"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-26be2859bfdcd8bc","number":"1035i","sourceNumber":"1035i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Em paciente com policitemia vera, podem ser consideradas manifestações clínicas decorrentes da hiperviscosidade sanguínea:","options":{"A":"Desidratação; perda de peso; ascite; linfadenomegalia","B":"Anemia; cálculo renal; icterícia; petéquias","C":"Eritromelalgia; hiperpotassemia; febre; hipóxia","D":"Vertigem; cefaleia, zumbido; hipertensão sistólica"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Quando o sangue fica 'grosso demais' (hiperviscosidade) na policitemia vera, isso atrapalha a circulação nos vasinhos pequenos, principalmente do cérebro — causando tontura, dor de cabeça, zumbido no ouvido, e mexendo até com a pressão arterial (deixando a sistólica mais alta).","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352517","ankiGuid":"F9;&<+B%Gp"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-586240dcd5a774b0","number":"1036i","sourceNumber":"1036i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"A respeito do linfoma de Hodgkin, é correto afirmar:","options":{"A":"Ocorrem mais frequentemente em crianças abaixo de 15 anos, idosos entre 50 e 60 anos, e mulheres","B":"Apenas uma minoria pode ser curada com o tratamento disponível hoje","C":"A doença se espalha desordenadamente, acometendo aleatoriamente grupos de linfonodos","D":"Pessoas com imunossupressão (HIV, uso de imunossupressores para rejeição) tem mais risco de desenvolver a doença"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Pessoas com o sistema imune enfraquecido (por HIV ou por remédios imunossupressores usados após transplantes, por exemplo) têm mais risco de desenvolver linfoma de Hodgkin — o vírus Epstein-Barr, que costuma estar mais ativo nesses pacientes, é um dos fatores ligados a essa doença.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352518","ankiGuid":"E9KhNL2z:I"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-0d3258b708746504","number":"1037i","sourceNumber":"1037i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Homem com 35 anos informa que tem observado o aparecimento de vários linfonodos indolores, aumentado de tamanho, na região cervical nos últimos 30 dias, febril (>38 °C), suores noturnos, perda de mais de 10% do peso sem causa aparente, fadiga e prurido. Teve diagnóstico de Linfoma de Hodgkin esses sintomas são classificados como","options":{"A":"Sintomas A","B":"Sintomas B","C":"Sintomas C","D":"Sintomas D"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Febre, suor noturno, perda de peso importante e prurido — esse conjunto de sintomas gerais do corpo, num paciente com linfoma de Hodgkin confirmado, são chamados de 'sintomas B' (em contraste com os pacientes sem esses sintomas, chamados de 'sintomas A'). Eles são importantes porque ajudam a definir o estadiamento da doença e influenciam o tratamento.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352519","ankiGuid":"K5QX^wrqM("},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-2bb0704ea12b5126","number":"1038i","sourceNumber":"1038i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"O linfoma de zona marginal esplênico está associado a infecção com o:","options":{"A":"Helicobacter pylori","B":"Chlamydophila psittaci","C":"Vírus da hepatite C","D":"Campylobacter jejuni"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"O linfoma de zona marginal esplênico (que afeta o baço) tem uma associação bem conhecida com a infecção pelo vírus da hepatite C — em alguns casos, tratar a hepatite C pode até ajudar a controlar o linfoma.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352520","ankiGuid":"P0Z3<(#:K*"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-ade6977fa1715fa7","number":"1039i","sourceNumber":"1039i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Paciente de 68 anos foi ao cirugião geral para avaliação de hérnia inguinal. O médico fez a avaliação e solicitou exames pré-operatórios que demonstraram um hemograma com hemoglobina de 13,9 g/dl, plaquetas de 208.000, leucócitos totais de 32800 com 88% de linfócitos. O hematologista fez um esfregaço de sangue periférico que demonstrava predomínio de linfócitos pequenos e alguns raros prolinfócitos, além de manchas de Gumprecht. O diagnóstico do paciente é:","options":{"A":"Leucemia linfoide aguda","B":"Mononucleose aguda","C":"Reação leucemoide","D":"Leucemia linfoide crônica"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Idoso descoberto por acaso (exame pré-operatório de rotina) com leucócitos bem altos (32.800), predominando linfócitos pequenos e maduros, com manchas de Gumprecht no esfregaço (restos de linfócitos frágeis que se rompem ao fazer a lâmina, um achado bem característico) — é o retrato clássico da leucemia linfoide crônica.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352521","ankiGuid":"A}_K)B)w[D"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-0bbe95fc6165add8","number":"1040i","sourceNumber":"1040i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"As linfonodomegalias (aumento dos linfonodos) localizadas ou disseminadas são características de uma enorme gama de patologias em pediatria. Nas linfonodomegalias é CORRETO afirmar:","options":{"A":"Linfonodomegalia localizada, com febre por mais de 7 dias descarta linfomas, lúpus eritematoso sistêmico e tuberculose","B":"O ácido úrico é encontrado em quantidade elevada nas células neoplásticas e pode estar aumentado nas linfonodomegalias por linfomas e/ou leucemias","C":"É mais evidente e frequente no período neonatal, pois o tecido linfático está aumentado de volume para proteger o recém-nascido da exposição a antígenos que acontece durante a infância","D":"Os linfonodos retroauriculares e supraclaviculares são considerados reacionais"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"O ácido úrico realmente pode aparecer aumentado no sangue de crianças com linfomas ou leucemias, porque as células neoplásicas se renovam (e morrem) muito rápido, liberando esse subproduto em excesso — é o mesmo mecanismo por trás da síndrome de lise tumoral.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352522","ankiGuid":"Os:syX8BrB"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-4dce8d253981369a","number":"1041i","sourceNumber":"1041i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"As linfonodomegalias localizadas ou disseminadas são características de uma enorme gama de patologias na infância e são queixas frequentes no ambulatório de pediatria. Qual a assertiva correta com relação a indicação de biópsia do linfonodo?","options":{"A":"Biopsiar linfonodos localizados elásticos, móveis, indolores, de tamanho menores que 2 a 3 cm","B":"Biopsiar linfonodos dolorosos, com sinais flogísticos e pouco aderidos a planos profundos","C":"Biopsiar linfonodos persistentes e sem redução após 2 semanas de antibioticoterapia","D":"Biopsiar linfonodos cervicais e epitrocleares de até 2,5 cm na ausência de infecção"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Um dos critérios pra indicar biópsia de um gânglio numa criança é ele continuar do mesmo jeito (ou não diminuir) mesmo depois de 2 semanas de um tratamento adequado com antibiótico — se não melhorou com o tratamento pra causa mais comum (infecção), é hora de investigar outras possibilidades, como um linfoma.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352523","ankiGuid":"Q~z$}B/:)v"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-522e6b5d535266d7","number":"1042i","sourceNumber":"1042i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Uma paciente de 28 anos de idade, percebendo uma massa indolor em crescimento lento no lado esquerdo do pescoço, procurou um clínico geral. A paciente tinha sudorese noturna e episódios de febre de 38° C, sem motivo aparente. Depois de ela negar existência de infecções no trato respiratório superior e perda de peso, o médico constatou que não havia mais alterações dignas de nota. No exame físico, encontrava-se afebril, com sinais vitais dentro da normalidade, mas foi encontrada uma massa de 4 cm, móvel, firme, arrendondada e indolor à palpação na metade direita do pescoço. Não tinha outra linfadenopatia periférica. O fígado e o baço não estavam aumentados. O médico levantou a hipótese diagnóstica de Linfoma de Hodgkin. A partir do caso clínico descrito, julgue o item a seguir. O método mais adequado para a confirmação do diagnóstico em tela é a punção aspirativa da massa cervical com agulha fina, seguida pela realização de cortes de tecido, buscando-se o reconhecimento do vírus do Epstein-Barr (VEB).","options":{"A":"Certo","B":"Errado"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"A frase está errada: pra confirmar um diagnóstico de linfoma de Hodgkin, não basta uma punção com agulha fina (que só coleta algumas células soltas, sem mostrar a arquitetura do gânglio) — é preciso fazer uma biópsia excisional (retirar o gânglio inteiro), pra ver a estrutura completa e encontrar as células de Reed-Sternberg, que são a assinatura dessa doença.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352524","ankiGuid":"voH<)oimTt"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-55c73ebbbc3da060","number":"1043i","sourceNumber":"1043i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Certo paciente de 35 anos de idade compareceu a uma consulta, informando histórico de febre, emagrecimento e linfonodomegalias mediastinais, sendo que há linfonodos de 3 cm em cadeia paratraqueal esquerda e paratraqueal direita. Ele também apresenta linfonodomegalia em cadeias axilares e inguinais. Diante desse quadro, é levantada a hipótese de linfoma. A respeito desse caso clínico, julgue o item a seguir. Deve-se indicar mediastinoscopia, pois a cadeia paratraqueal, além de ser bem abordada, oferece um linfonodo de melhor rendimento para o diagnóstico de linfoma, se comparado ao inguinal.","options":{"A":"Certo","B":"Errado"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"A frase está errada: quando já existem gânglios acessíveis e aumentados em outras regiões (como axila e virilha), o ideal é biopsiar esses primeiros — são bem mais fáceis de alcançar e menos invasivos do que fazer uma mediastinoscopia (procedimento cirúrgico mais complexo pra acessar gânglios dentro do tórax), que fica reservada pra quando não há outra opção mais acessível.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352525","ankiGuid":"I/%|8k+EoU"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-c7bc979533194dc6","number":"1044i","sourceNumber":"1044i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Quanto à Leucemia Mieloide Crônica (LMC), assinale a alternativa correta.","options":{"A":"O esfregaço do sangue periférico mostra leucocitose com desvio escalonado, com neutrófilos apresentando granulações tóxicas, associados a elevação do VHS e PCR","B":"A presença de anemia, esplenomegalia e trombocitopenia (contagem de plaquetas inferior a 90.000) são achados comuns ao diagnóstico e são critérios de doença crônica (considerada fase indolente da doença)","C":"É considerada doença indolente semelhante à Leucemia Linfocítica Crônica (LLC) e deve ser monitorada sem tratamento até critérios clínicos de início de tratamento como: trombocitopenia, presença de blastos na periferia acima de 10% e basofilia","D":"As translocações envolvendo os cromossomos 9 e 22 são presentes em 90% a 95% dos casos, sendo o respectivo gene de fusão o gene BCR-ABL","E":"Os inibidores de tirosina quinase (TKI) não modificaram a sobrevida média desses pacientes, que continua sendo de quatro anos a partir da fase acelerada da doença"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"A leucemia mieloide crônica é causada por uma troca de pedaços entre os cromossomos 9 e 22 (formando o famoso 'cromossomo Philadelphia'), presente em 90-95% dos casos, e essa troca gera um gene novo chamado BCR-ABL, responsável por manter a célula doente se multiplicando sem parar — é o alvo exato dos remédios usados no tratamento (os inibidores de tirosina quinase).","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352526","ankiGuid":"l_LIMP|Ucx"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-adc16e8df151c6fd","number":"1045i","sourceNumber":"1045i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Uma paciente com síndrome de Sjögren primária que foi diagnosticada há 6 anos e tratado com lágrimas artificial para alívio dos sintomas, apresentou inchaço da parótida nos últimos 3 meses. Ela também notou aumento dos linfonodos cervicais posteriores. A avaliação mostra leucopenia e baixos níveis de complemento de C4. Qual é o diagnóstico mais provável?","options":{"A":"Amiloidose","B":"Pancreatite crônica","C":"Infecção pelo HIV","D":"Linfoma"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Paciente com síndrome de Sjögren (doença autoimune que afeta as glândulas), que agora desenvolveu inchaço na parótida, gânglios aumentados, leucopenia e complemento baixo — esse conjunto de sinais é um alerta clássico de que a doença de base pode estar evoluindo para um linfoma (o Sjögren é uma das condições autoimunes com maior risco de desenvolver linfoma, geralmente do tipo MALT).","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352527","ankiGuid":"pWyA$,rLX["},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-ea299841831cf7bd","number":"1046i","sourceNumber":"1046i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Em um estudo retrospectivo com 2556 pacientes atendidos em serviços primários de saúde e que apresentavam adenomegalia sem etiologia definida, observou-se prevalência de 1,1% de malignidade. Em relação ao risco de malignidade nas adenomegalias, podemos afirmar:","options":{"A":"A idade maior que 40 anos não é um fator de risco","B":"É mais frequente quando a localização for supraclavicular","C":"É mais comum nas adenomegalias com consistência diminuída","D":"A duração maior que 4 semanas é mais comum nos de origem infecciosas"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Entre os locais de gânglios aumentados, a região supraclavicular (acima da clavícula) é a que carrega o maior risco de esconder uma doença maligna por trás, sendo por isso sempre encarada com mais cautela do que gânglios em outras regiões do corpo.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352528","ankiGuid":"OtGv0J).dg"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-9d209e8a40ae92eb","number":"1047i","sourceNumber":"1047i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Paciente com 65 anos de idade, refere aumento de região cervical com duração maior que 60 dias. Ao exame físico foram evidenciados linfonodos palpáveis na região cervical posterior, indolores e não aderentes aos planos profundos. Após esgotada propedêutica de orofaringe e trato digestivo superior foi realizada biopsia excisional de linfonodo comprometido que demonstrou a presença de células grandes, com citoplasma discretamente basofílico, núcleos bilobulados, circundadas por linfócitos T. Assinale a alternativa CORRETA para o diagnóstico MAIS PROVÁVEL desse caso:","options":{"A":"Linfoma de Burkitt","B":"Linfoma de Hodgkin","C":"Linfoma linfoplasmocitário","D":"Linfoma folicular"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Células grandes com citoplasma meio pálido, núcleos com dois lóbulos, cercadas de linfócitos T — essa descrição bate exatamente com a célula de Reed-Sternberg (ou suas variantes), a marca registrada do linfoma de Hodgkin no exame microscópico.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352529","ankiGuid":"EFDb^ypxG{"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-d24eeae07edb008b","number":"1048i","sourceNumber":"1048i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Um paciente de 72 anos de idade foi internado na enfermaria de um hospital devido a quadro de astenia intensa, palpitação e dispneia aos esforços nos últimos sete dias. Ao exame físico, apresentou-se hipocorado 3+/4+, com espaço de Traube ocupado, hemoglobina de 6,1 g/dl, VCM e CHCM dentro da normalidade e leucócitos de 20.700/mm³, com desvio escalonado até mielócitos. A análise do esfregaço mostrou hemácias em lágrimas e macroplaquetas. Com base nessa situação hipotética, assinale a alternativa que apresenta o provável diagnóstico do paciente:","options":{"A":"Leucemia mieloide crônica","B":"Enterobacteriose prolongada","C":"Calazar","D":"Mielofibrose","E":"Anemia da insuficiência hepática"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Cansaço, palpitação e falta de ar num idoso, com anemia bem grave (Hb 6,1), baço aumentado (espaço de Traube ocupado), leucócitos com escalonamento de células mieloides até formas jovens (mielócitos), e o achado no esfregaço de hemácias em lágrima (dacriócitos) e macroplaquetas (plaquetas gigantes) — esse conjunto de achados é bem clássico da mielofibrose, uma doença em que a medula é substituída por fibrose, empurrando a produção de sangue pra fora dela (baço e fígado assumem essa função, causando o aumento do baço).","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352530","ankiGuid":"jRey9H:m]S"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-7087c08de9036b94","number":"1049i","sourceNumber":"1049i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Um paciente de 39 anos comparece a uma consulta de rotina, sem nenhuma queixa. O exame físico revelou-se normal. Dentre os testes solicitados, verificou-se o seguinte hemograma (repetido e confirmado): Hb 13,2 g/dl; VCM 82 fL; Leucócitos 45.500/mm³; Segmentados 70%; Bastonetes 10%; Metamielócitos 5%; Mielócitos 4%; Blastos 1%; Linfócitos 5%; Eosinófilos 5%; Plaquetas 580.000/mm³. Diante disso, foram solicitados: VHS 15 mm; Proteína C Reativa 1,0mg/l; Ultra Sonografia de Abdome Total: apenas pequenos cistos renais. Diante do quadro exposto acima, pode-se concluir que:","options":{"A":"Trata-se de Leucocitose reacional, pois o paciente encontra-se assintomático e não há sequer esplenomegalia, para se considerar Leucemia Mieloide Crônica (LMC)","B":"O diagnóstico mais provável é mielofibrose primária; o próximo passo seria a realização da biópsia de medula óssea","C":"O mielograma e a citometria de fluxo seriam os próximos passos; tais exames confirmariam ou excluiriam LMC, além de abordar possíveis outros diagnósticos diferenciais","D":"O diagnóstico de Leucemia Mieloide Crônica (LMC) deve ser considerado; o próximo passo seria a pesquisa do cromossomo Philadelphia ou da mutação bcr-abl"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Homem sem sintomas, achado por acaso com leucócitos bem altos (45.500) mostrando todas as fases de maturação das células mieloides — mesmo sem sintomas ou baço palpável, esse padrão de escalonamento celular já é bem sugestivo de leucemia mieloide crônica, e o próximo passo é confirmar com a pesquisa do cromossomo Philadelphia ou da mutação bcr-abl.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352531","ankiGuid":"z9LNybWt}J"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-b1cd88d32464e818","number":"1050i","sourceNumber":"1050i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Sobre a Doença de Hodgkin, coloque V (verdadeiro) ou F (falso) nas afirmativas abaixo e assinale a opção correta. ( ) Adenopatia hilar pode levar a tosse. ( ) Os pacientes com sintomas tipo B costumam fazer um ciclo completo de quimioterapia. ( ) Apresenta-se geralmente por aumento assintomático de linfonodo. ( ) A cura aproxima-se de 60% em paciente com doença localizada. ( ) Os sintomas tipo B incluem: febre, sudorese noturna e emagrecimento.","options":{"A":"(V) (F) (F) (F) (V)","B":"(V) (V) (V) (F) (V)","C":"(F) (F) (V) (V) (V)","D":"(F) (V) (F) (F) (F)","E":"(V) (V) (V) (F) (F)"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Vamos por item: adenopatia hilar (gânglios perto dos brônquios) realmente pode comprimir e causar tosse (V). Pacientes com sintomas B fazem sim o ciclo completo de tratamento (V). A doença de Hodgkin geralmente aparece mesmo como um gânglio aumentado sem outros sintomas (V). Já a chance de cura em doença localizada é bem MAIOR que 60% hoje em dia (com tratamento moderno, costuma passar de 80-90%) — essa frase está errada (F). E os sintomas B realmente incluem febre, suor noturno e emagrecimento (V). Sequência: V, V, V, F, V.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352532","ankiGuid":"u]_(JRUg{S"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-ead823e81673a4de","number":"1051i","sourceNumber":"1051i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Paciente feminina, 15 anos, apresenta história de tumoração cervical há aproximadamente 3 meses com crescimento em velocidade moderada, consistência fibroelástica e aderida a planos profundos. Nega febre, emagrecimento, sudorese ou outros sintomas. Exame físico sem outras alterações. Realizada biópsia da lesão com anatomopatológico sugestivo de doença linfoproliferativa e presença de células de Reed-Sternberg. Tomografias de tórax, abdome superior e pelve sem alterações. Com os dados apresentados qual é o diagnóstico desta paciente, estadiamento clínico e tratamento indicado?","options":{"A":"Linfoma de grandes células B, estadiamento IA, quimioterapia","B":"Linfoma de Burkitt, estadiamento IIB, radioterapia associada a quimioterapia","C":"Linfoma de Hodgkin, estadiamento IB, quimioterapia","D":"Linfoma não Hodgkin, estadiamento IA, radioterapia","E":"Linfoma de Hodgkin, estadiamento IA, radioterapia"},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Adolescente com massa no pescoço crescendo devagar, sem sintomas gerais (sem febre, sem perda de peso), com biópsia mostrando células de Reed-Sternberg (a marca do linfoma de Hodgkin) e tomografias sem outras alterações (mostrando que a doença está localizada, sem sintomas B) — é linfoma de Hodgkin em estágio inicial (IA), tratado com radioterapia, uma opção eficaz pra doença bem localizada.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352533","ankiGuid":"zIhp}od;95"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-b8903e5e10c34ede","number":"1052i","sourceNumber":"1052i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"A translocação entre os braços longos dos cromossomos 9 e 22 caracteriza qual neoplasia hematológica?","options":{"A":"Leucemia linfocítica crônica","B":"Tricoleucemia","C":"Leucemia mieloide crônica","D":"Mielofibrose primária","E":"Mieloma múltiplo"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"A troca de pedaços entre os braços longos dos cromossomos 9 e 22 (formando o cromossomo Philadelphia) é a marca registrada da leucemia mieloide crônica.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352534","ankiGuid":"n|mu[ky_M("},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-939077ae13b554ca","number":"1053i","sourceNumber":"1053i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"No que diz respeito ao linfoma de Hodgkin, assinale a alternativa ERRADA:","options":{"A":"A afecção, cuja incidência atinge o pico por volta dos 30 anos, inicia-se mais frequentemente nos linfonodos cervicais, progredindo por contiguidade","B":"Do ponto de vista histopatológico, o linfoma de Hodgkin clássico, tipo celularidade mista, caracteriza-se por aspecto celular heterogêneo e, particularmente, pela ausência de eosinófilos","C":"Em jovens com linfoma de Hodgkin clássico, tipo esclerose nodular, é frequente o acometimento do mediastino","D":"Nas células de Hodgkin e nas células de Reed-Sternberg, é frequente a expressão imuno-histoquímica de uma proteína do vírus Epstein-Barr"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"A frase errada é a B: o linfoma de Hodgkin clássico do tipo celularidade mista tem justamente um aspecto celular bem heterogêneo, que INCLUI eosinófilos (não a ausência deles) — dizer que eosinófilos estão ausentes está errado. As outras frases (pico de incidência aos 30 anos, começo em gânglios cervicais com progressão por contiguidade, acometimento do mediastino no subtipo esclerose nodular em jovens, e a presença de proteínas do Epstein-Barr nas células de Hodgkin/Reed-Sternberg) estão corretas.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352535","ankiGuid":"DY?Lk)K$9O"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-8a5606b1e1e96a62","number":"1054i","sourceNumber":"1054i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Paciente masculino, 45 anos, pardo, com queixas vagas de fadiga e indisposição, náuseas e vômitos. Notou aumento do volume abdominal. Ao exame físico: discreta palidez e esplenomegalia acentuada e indolor. O estudo hematológico revelou: hemácias = 3,2 milhões/mm³; Hb = 9,8 g/dl; Ht = 29%; VCM = 90; HCM = 30,6: CHCM = 29,5; leucócitos = 187.000/mm³; blastos = 2%; promielócitos = 3%; mielócitos = 13%; metamielócitos = 10%; bastonetes = 20%; segmentados = 35%; eosinófilos = 3%; basófilos = 2%; linfócitos = 3%; monócitos = 4%; plaquetas = 1.065.000/mm³. Qual a hipótese diagnóstica mais provável?","options":{"A":"Reação leucemoide","B":"Trombocitemia essencial","C":"Leucemia mieloide aguda","D":"Leucemia mieloide crônica"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Cansaço, náuseas, aumento da barriga, baço enorme e indolor, com leucócitos extremamente altos (187.000!) mostrando todas as fases de maturação das células mieloides, e plaquetas bem altas também (mais de 1 milhão!) — é o retrato clássico da leucemia mieloide crônica.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352536","ankiGuid":"qGN(3vrrvz"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-c4177d50dee6635f","number":"1055i","sourceNumber":"1055i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Uma mulher com 66 anos de idade foi encaminhada ao ambulatório de hematologia de um hospital geral para investigação diagnóstica de pancitopenia. Em consulta, a paciente refere astenia progressiva nos últimos 3 meses e relata também que passou a apresentar, há 2 semanas, petéquias e gengivorragia. Diante disso, procurou atendimento médico, quando foi realizado hemograma completo que revelou anemia normocítica normocrômica, com baixa contagem de reticulócitos, leucopenia com diferencial normal e plaquetopenia. Um exame hematoscópico revelou a presença de elevada porcentagem de dacriócitos (\"hemácias em lágrima\"). Nessa situação, qual é o diagnóstico mais provável da paciente e que exame complementar deve ser solicitado para sua confirmação?","options":{"A":"Mielofibrose; biópsia de medula óssea","B":"Leucemia mieloide aguda; aspirado de medula óssea","C":"Mielodisplasia; citometria de fluxo de sangue periférico","D":"Aplasia de medula óssea; sorologia para parvovírus B19"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Cansaço, petéquias e sangramento de gengiva numa idosa, com pancitopenia (todas as três linhagens do sangue baixas), reticulócitos baixos, e a presença de muitos dacriócitos (hemácias em formato de gota) no esfregaço — quadro clássico de mielofibrose. O exame que confirma é a biópsia de medula óssea, já que o aspirado geralmente vem 'seco' por causa da fibrose que substitui a medula normal.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352537","ankiGuid":"yOk_wS|Bl#"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-e86cb863db235a04","number":"1056i","sourceNumber":"1056i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Na investigação de um homem de 24 anos, com quadro de linfadenopatia cervical persistente, foram encontrados, à microscopia óptica da biópsia excisional do linfonodo, os seguintes achados: células gigantes, multinucleadas, com núcleos bilobulados, nucléolos eosinofílicos, imersos em um infiltrado inflamatório fibrótico. O diagnóstico mais provável é:","options":{"A":"Linfoma difuso de grandes células B","B":"Linfoma de Hodgkin","C":"Tuberculose ganglionar","D":"Sarcoidose","E":"Mononucleose pelo Epstein-Barr vírus"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Células gigantes, com vários núcleos e núcleos em formato de dois lóbulos, com um 'olho' bem visível dentro (nucléolo eosinofílico), cercadas de tecido inflamatório com fibrose — essa é a descrição clássica da célula de Reed-Sternberg, a assinatura microscópica do linfoma de Hodgkin.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352538","ankiGuid":"M-ld`FWy5I"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-f17e8d3925300e65","number":"1057i","sourceNumber":"1057i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"É correto afirmar, em relação ao Linfoma de Hodgkin que:","options":{"A":"Evolui frequentemente com linfadenopatia dolorosa","B":"As células de Reed-Sternberg são muito sugestivas do diagnóstico","C":"A linfadenopatia palpável é um achado pouco frequente","D":"Os sintomas B indicam bom prognóstico","E":"O subtipo depleção linfocítica é o que apresenta melhor prognóstico"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"As células de Reed-Sternberg são a peça-chave do diagnóstico do linfoma de Hodgkin — encontrá-las na biópsia é bem sugestivo (embora não 100% exclusivo) dessa doença. As outras frases estão erradas: a linfadenopatia costuma ser INDOLOR (não dolorosa) e é achado bem FREQUENTE (não raro), os sintomas B indicam prognóstico PIOR (não bom), e o subtipo depleção linfocítica tem o pior prognóstico entre os subtipos (não o melhor).","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352539","ankiGuid":"p$qwFAQN;`"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-93cccfd224ad315d","number":"1058i","sourceNumber":"1058i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Homem de 38 anos com história de pneumonias de repetição nos últimos 2 anos e há um ano aparecimento de adenomegalias cervicais, axilares e inguinais. Hemograma normal há 3 anos e atualmente com os seguintes resultados: Hemoglobina=9,7g/dl, Leucócitos: 84.000/mm³ às custas de linfócitos maduros e Plaquetas = 68.000/mm³. Imunofenotipagem das células do sangue com presença de células B monoclonais com CD5 positivo. Beta 2 microglobulina elevada. Pico monoclonal em gamaglobulinas em eletroforese de proteínas séricas. Com os dados acima, qual é a alternativa CORRETA?","options":{"A":"Leucemia Linfoblástica Aguda, de alto risco","B":"Linfoma não Hodgkin difuso de grandes células B, estádio IIIB","C":"Leucemia Linfocítica Crônica, estádio CD de Binet","D":"Mieloma Múltiplo, International Staging System-ISS III"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Infecções de repetição (mostrando sistema imune comprometido), gânglios espalhados pelo corpo, anemia, leucócitos altos com linfócitos maduros, plaquetas baixas, células B monoclonais com marcador CD5 positivo (típico da LLC), beta-2-microglobulina alta (marcador de gravidade) e até um pico monoclonal de proteína (que pode ocorrer em alguns casos de LLC) — tudo aponta pra leucemia linfocítica crônica, num estágio já mais avançado (com anemia e plaquetopenia, correspondendo ao estádio C/D de Binet).","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352540","ankiGuid":"bdxU3{K&>T"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-6713b86f3d20f37f","number":"1059i","sourceNumber":"1059i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Homem, 68 anos de idade, foi avaliado devido à dispneia aos esforços. Ao exame físico, apresenta palidez da conjuntiva, ausculta cardíaca e pulmonar normais, ausência de linfonodomegalias, hepatomegalia ou esplenomegalia. Sem sinais de sangramento cutâneo-mucoso. Exames laboratoriais: Hb = 8 g/dl; hematócrito = 24%; volume corpuscular médio = 112 (normal de 80 a 100); leucócitos = 2.100/ml; plaquetas de 64.000/ml. Reticulócitos = 0,3% (normal de 0,5 a 1,5%); desidrogenase lática = 150 U/L (normal de 140 a 280). O paciente traz consigo um hemograma de dois anos antes com Hb de 10 g/dl, hematócrito de 30% e leucócitos e plaquetas normais. Qual é a principal hipótese diagnóstica?","options":{"A":"Leucemia mieloide aguda","B":"Anemia hemolítica","C":"Mielofibrose","D":"Insuficiência hepática – Child C","E":"Síndrome mielodisplásica"},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Idoso com falta de ar aos esforços, anemia (Hb 8, com hemácias grandes, VCM 112), leucócitos e plaquetas baixos, reticulócitos baixos (a medula não compensando), LDH normal (descartando hemólise ativa) — e um hemograma de dois anos atrás já mostrando piora progressiva. Esse padrão de pancitopenia progressiva com hemácias grandes, sem outra causa evidente, é bem sugestivo de síndrome mielodisplásica, uma doença em que a medula 'envelhece' e produz células defeituosas.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352541","ankiGuid":"JEe-Dpq,4/"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-eb46effe48c65e82","number":"1060i","sourceNumber":"1060i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Em relação à Leucemia Mielóide Crônica (LMC) é correto afirmar que:","options":{"A":"É a forma mais frequente de leucemia no mundo","B":"É uma doença de fases, que pode se transformar em leucemia aguda","C":"Raramente está associada com a presença do cromossomo Philadelphia","D":"Seu tratamento é baseado em poliquimioterapia"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"A leucemia mieloide crônica passa por fases (crônica, acelerada e crise blástica) e, se não tratada adequadamente, pode evoluir pra uma forma aguda e mais agressiva — por isso é tão importante o diagnóstico e tratamento precoce com os inibidores de tirosina quinase.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352542","ankiGuid":"qN_Lw/mJ9R"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-1d259761deadbbc6","number":"1061i","sourceNumber":"1061i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"No passado, a leucemia mieloide crônica era doença com sobrevida global de cerca de 3-7 anos. Atualmente, a sobrevida em 8-10 anos é estimada em cerca de 90%. A intervenção terapêutica responsável pela alteração na história natural desta doença foi (foram):","options":{"A":"A terapia celular com o transplante alogênico de medula óssea","B":"O inibidor da tirosina quinase resultante do oncogene BCR/ABL1","C":"A combinação de imunoterapia com alfa interferon e inibidor do oncogene P53","D":"Os inibidores do gene Jak-2 localizado no cromossomo Filadélfia"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"O grande avanço que mudou completamente o prognóstico da leucemia mieloide crônica foi a descoberta dos inibidores de tirosina quinase (como o imatinibe), que bloqueiam diretamente a proteína anormal (BCR-ABL) produzida pelo cromossomo Philadelphia — transformando uma doença que matava a maioria dos pacientes em poucos anos numa condição controlável a longo prazo.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352543","ankiGuid":"N+]1&b;{sx"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-29f7e8dc7cbadf4d","number":"1062i","sourceNumber":"1062i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Em relação às Leucemias e Linfomas, é correto afirmar, EXCETO:","options":{"A":"O Linfoma MALT (Tecido Linfoide Associado à Mucosa) é mais incidente no trato gastrointestinal e tem imunofenótipo B","B":"O Linfoma Hodgkin é um linfoma de alto grau, cujos protocolos de tratamento incluem, de início, quimioterapia seguida de transplante de células autólogas","C":"A Leucemia Promielocítica está associada a sangramentos precoces e, quando tem a alteração citogenética: t(15:17), tem melhor prognóstico","D":"A Leucemia/Linfoma T do Adulto está associada ao vírus HTLV1","E":"Nos linfomas de baixo grau assintomáticos, a terapia e/ou seguimento (watch and wait) são discutíveis"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"A frase errada é a B: o transplante de células autólogas não é feito 'de início' no tratamento do linfoma de Hodgkin — ele é reservado pra casos de recaída ou doença que não respondeu ao tratamento inicial, não como primeira linha de tratamento. As outras frases (sobre o linfoma MALT, a leucemia promielocítica e seu prognóstico com t(15;17), a leucemia/linfoma T do adulto ligada ao HTLV1, e a conduta de observação em linfomas de baixo grau assintomáticos) estão corretas.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352544","ankiGuid":"i{,C(Hs}w]"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-fc36760766df035c","number":"1063i","sourceNumber":"1063i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Um paciente de 20 anos procurou o médico com queixas de dispneia aos esforços, febre com sudorese noturna e perda de peso há seis meses, além do surgimento de massas cervicais que doíam, quando ingeria bebida alcoólica. Ao exame físico, percebiam-se linfonodomegalias em cadeias cervical anterior e posterior direita, de consistência firme e indolor. Tomografia de tórax evidenciou aglomerado de linfonodos mediastinais. Com base no quadro descrito, qual o diagnóstico mais provável?","options":{"A":"Linfoma de Hodgkin subtipo esclerose nodular","B":"Linfoma não Hodgkin","C":"Sarcoidose","D":"Tuberculose ganglionar","E":"Carcinoma de mama metastático"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Falta de ar, febre com suor noturno, perda de peso, massas no pescoço que doem depois de beber álcool (um sinal raro mas bem específico!) e gânglios aumentados no mediastino — tudo aponta pra linfoma de Hodgkin, subtipo esclerose nodular (o mais comum em jovens, principalmente com acometimento do mediastino).","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352545","ankiGuid":"l7Fdb{DT>:"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-1679032bc78f2e67","number":"1064i","sourceNumber":"1064i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Paciente de cinco anos de idade há sete dias apresenta quadro de linfadenomegalia generalizada, hepatomegalia e febre baixa. Qual dos achados clínicos abaixo NÃO é considerado sinal de alertas para doença maligna?","options":{"A":"Emagrecimento e palidez cutâneo-mucosa","B":"Linfadenomegalia com sinais inflamatórios","C":"Linfonodos aderentes aos planos profundo ou superficial","D":"Linfonodos com consistência aumentada"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Entre os sinais listados, ter gânglios inflamados (vermelhos, quentes, doloridos) é justamente o que MENOS preocupa com câncer — sinais inflamatórios geralmente apontam pra uma causa infecciosa/reativa comum, diferente de gânglios malignos, que costumam ser indolores, endurecidos e aderidos aos tecidos ao redor.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352546","ankiGuid":"oV0j=HB2y&"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-aa12bd029a21c179","number":"1065i","sourceNumber":"1065i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Determinado paciente, 72 anos de idade, comparece ao pronto-socorro queixando-se de que, há vários meses, evolui com cefaleia holocraniana, turvação visual, face e olhos avermelhados e prurido generalizado após o banho. Começou também a apresentar pressão alta, sendo que realiza consultas médicas anuais sem detecção de nenhuma patologia. Ao exame físico, notam-se hepatomegalia e PA = 180 mmHg x 100 mmHg, eritema conjuntival e face eritematosa. Foi realizado hemograma que revelou hemoglobina = 19 mg/dL, leucócitos = 15.700 e plaquetas = 500 mil. Acerca desse caso clínico, assinale a alternativa CORRETA.","options":{"A":"O tratamento envolve fludarabina e rituximab","B":"O transplante de medula óssea é o tratamento de escolha para a maioria dos pacientes","C":"O uso de sangrias terapêuticas é indicado","D":"A anticoagulação é indicada em razão da hiperviscosidade sanguínea","E":"A mutação JAK 2 confirma o diagnóstico e é exigida para ele"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Dor de cabeça, visão embaçada, cara e olhos vermelhos, coceira depois do banho, pressão alta nova, fígado aumentado e hemoglobina bem alta (19!) — quadro clássico de policitemia vera. O tratamento inicial pra baixar rapidamente a quantidade de sangue (e a viscosidade) são as sangrias terapêuticas (flebotomias), que retiram sangue do paciente periodicamente.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352547","ankiGuid":"Ic|CRw1>_|"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-66c65cd60435a542","number":"1066i","sourceNumber":"1066i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Um paciente de cinquenta anos de idade procurou atendimento médico queixando-se de fadiga, perda de peso, mal-estar e empachamento pós-prandial. Em seu exame clínico, o achado de destaque foi esplenomegalia. O hemograma apresentou os seguintes resultados: leucocitose = 320.000 leucócitos/mL, com predomínio de neutrófilos e desvio à esquerda, estendendo-se até blastos; basofilia e eosinofilia presentes; plaquetas com contagem normal; e anemia normocrômica e normocítica discreta. Ademais, constatou-se a presença do cromossomo Filadélfia (Ph) em células da medula óssea. Com relação a esse caso clínico, julgue o próximo item. No caso em apreço, o principal diagnóstico é leucemia mieloide crônica.","options":{"A":"Certo","B":"Errado"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Cansaço, perda de peso, saciedade precoce, baço aumentado, leucócitos extremamente altos com todas as fases de maturação das células mieloides até blastos, basofilia e eosinofilia, e o cromossomo Philadelphia positivo na medula — tudo confirma o diagnóstico de leucemia mieloide crônica.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352548","ankiGuid":"B+/<5P!]Yf"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-6cb7371691f7349c","number":"1067i","sourceNumber":"1067i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"O paciente é um homem de 50 anos referindo plenitude pós-prandial mesmo após comer pequenas quantidades. Encontra-se hipocorado, anictérico e baço palpável 8 cm abaixo da reborda costal. O resto do exame físico é normal. Ht = 37%; plaquetas = 377.000/mm³. Contagem de leucócitos com 50.000/mm³, granulócitos = 43%; bastões = 13%; metamielócitos = 18%; mielócitos = 10%; promielócitos = 2%; blastos = 2%; monócitos = 11%; basófilos = 2%, eosinófilos = 2%; linfócitos = 1%. Qual é o diagnóstico mais provável?","options":{"A":"Leucemia linfocítica crônica","B":"Leucemia mieloide crônica","C":"Leucemia mieloide aguda","D":"Anemia megaloblástica"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Sensação de estômago cheio rápido demais, baço bem grande (8cm abaixo da costela), leucócitos altos (50.000) mostrando todas as fases de maturação das células mieloides — é o retrato clássico da leucemia mieloide crônica.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352549","ankiGuid":"x!%fHkHK,1"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-3c4a2428980e8d0d","number":"1068i","sourceNumber":"1068i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Qual das seguintes proteínas quiméricas é expressa pela codificação do gene de fusão presente no cromossomo Philadelphia [t(9,22)] em pacientes portadores de leucemia mieloide crônica?","options":{"A":"E2a-Pbx1","B":"MLL-ENL","C":"ETV6-NTRK3","D":"BCR-ABL1","E":"FIP1-PDGFR a"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"A troca entre os cromossomos 9 e 22 (cromossomo Philadelphia) gera um gene de fusão chamado BCR-ABL1, que produz uma proteína anormal que fica 'ligada' o tempo todo, mandando a célula se multiplicar sem parar — é justamente essa proteína que os remédios usados no tratamento (inibidores de tirosina quinase) bloqueiam.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352550","ankiGuid":"J;($WX%Uay"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-35bddd86a6035658","number":"1069i","sourceNumber":"1069i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Homem, 46 anos, procura a unidade de emergência com história de febre baixa diária (até 37,8°C) e episódios de sudorese noturna há 15 dias. Refere perda de peso nos últimos 2 meses, de 82 para 75 kg. Exame Físico: bom estado geral; PA = 130 x 80 mmHg; FC = 72 bpm; palidez cutânea; linfonodos de até 1 cm de diâmetro em cadeias cervicais anteriores e posteriores; e inguinais bilateralmente. Baço palpável a 2 cm do rebordo costal esquerdo. Hemograma: Hb = 10,6 g/dl; leucócitos = 29.000/mm³ (segmentados = 54%; bastonetes = 12%; metamielócitos = 6%; mielócitos = 4%; promielócitos = 4%; blastos = 1%; linfócitos = 13%; eosinófilos = 3%; basófilos = 2%; monócitos = 1%); plaquetas = 567.000/mm³. A HIPÓTESE DIAGNÓSTICA E A CONDUTA SÃO:","options":{"A":"Leucocitose reacional, investigação de foco infeccioso","B":"Leucemia aguda, esfregaço e cariótipo de medula óssea","C":"Linfoma não Hodgkin/leucemia linfoide/crônica, biópsia de medula óssea","D":"Leucemia mieloide crônica, esfregaço e cariótipo de medula óssea"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Febre baixa diária, suor noturno, perda de peso, gânglios espalhados pelo corpo, baço palpável, e leucócitos moderadamente altos (29.000) mostrando o escalonamento típico de células mieloides (do mais jovem ao mais maduro) — esse padrão sugere leucemia mieloide crônica, mesmo sem uma leucocitose extremamente alta. A investigação segue com esfregaço e cariótipo de medula óssea, buscando o cromossomo Philadelphia.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352551","ankiGuid":"K9qGJ7m@3)"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-baa9b2f18c7475bc","number":"1070i","sourceNumber":"1070i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"A síndrome mieloproliferativa que está associada ao cromossomo Philadelphia é:","options":{"A":"Policitemia vera","B":"Trombocitemia essencial","C":"Mielofibrose","D":"Leucemia linfoide aguda","E":"Leucemia mieloide crônica"},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Entre as doenças mieloproliferativas (policitemia vera, trombocitemia essencial, mielofibrose e leucemia mieloide crônica), a única classicamente associada ao cromossomo Philadelphia é a leucemia mieloide crônica — as outras três geralmente estão ligadas a outra mutação, a JAK2.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352552","ankiGuid":"muwgJ7Q]Nu"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-b24c5c4e200462f5","number":"1071i","sourceNumber":"1071i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Os linfomas podem ser classificados como Hodgkin e não Hodgkin. Na doença de Hodgkin, há proliferação das células neoplásicas de Reed-Sternberg. O linfoma não Hodgkin é um grupo heterogêneo de doenças que surgem a partir de alterações clonais dos linfócitos B e T. Assinale a opção INCORRETA:","options":{"A":"O linfoma de Burkitt tem imunofenótipo B e é altamente agressivo","B":"O linfoma difuso de grandes células B, CD20 positivo, é de alto grau e tem boa resposta à quimioterapia associada ao anticorpo monoclonal rituximabe","C":"O linfoma folicular é de baixo grau e costuma associar-se ao gene bcl-2","D":"O linfoma MALT (tecido linfoide associado à mucosa) tem imunofenótipo T e apresenta alto grau de malignidade","E":"O linfoma T-ATL está associado ao vírus HTLV1"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"A frase errada é a D: o linfoma MALT tem imunofenótipo B (não T, como diz a alternativa) e é um linfoma de BAIXO grau de malignidade (não alto grau) — a alternativa erra nos dois pontos. As outras frases (sobre o linfoma de Burkitt, o linfoma difuso de grandes células B respondendo bem ao rituximabe, o linfoma folicular associado ao gene bcl-2, e o linfoma T-ATL ligado ao HTLV1) estão corretas.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352553","ankiGuid":"KU7D+c[s%B"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-de29359abb171844","number":"1072i","sourceNumber":"1072i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Das doenças a seguir, qual apresenta risco maior de desenvolvimento de linfoma quando comparado à população geral?","options":{"A":"Lúpus eritematoso sistêmico","B":"Doença de Behçet","C":"Síndrome de Sjögren","D":"Policondrite recidivante"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Entre as doenças autoimunes listadas, a síndrome de Sjögren tem a associação mais forte e conhecida com o desenvolvimento de linfoma, comparada com a população geral.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352554","ankiGuid":"C4</.^qI0d"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-ab54359ff0e65b2e","number":"1073i","sourceNumber":"1073i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Diante do seguinte paciente: sexo masculino, de 65 anos de idade, com quadro de febre predominantemente noturna, calafrios, perda ponderal, prurido, linfonodos cervicais de tamanho aumentado. Na biopsia do linfonodo, o patologista visualizou células de Reed Sternberg. O diagnóstico mais provável é:","options":{"A":"Leucemia mieloide aguda","B":"Linfoma não Hodgkin","C":"Leucemia mieloblástica","D":"Linfoma de Hodgkin","E":"Linfoma de Burkitt"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Febre à noite, calafrios, perda de peso, coceira na pele e gânglios aumentados no pescoço, com a biópsia mostrando células de Reed-Sternberg — é o retrato clássico do linfoma de Hodgkin.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352555","ankiGuid":"Fr;{c.L3uC"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-4a90328530fa1f0f","number":"1074i","sourceNumber":"1074i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Um paciente de 67 anos de idade procura o médico para a realização de check-up. Ele não apresentava queixas, era um indivíduo ativo (atividade física 4 vezes por semana), negava etilismo, negava tabagismo, negava possuir comorbidades. O exame físico não apresentava particularidades. Nos exames laboratoriais solicitados, apresentou o seguinte resultado de hemograma: hematócrito = 39%; hemoglobina = 13,9 g/dl; leucócitos = 37.000/mm³; neutrófilos = 24%; linfócitos = 70%; eosinófilos = 1%; monócitos = 5%; plaquetas = 250.000. Para o paciente acima, a hipótese mais provável é:","options":{"A":"Leucemia linfoblástica aguda","B":"Leucemia linfocítica crônica","C":"Síndrome mielodisplásica","D":"Trombocitemia essencial","E":"Leucemia mieloide crônica"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Idoso ativo, sem sintomas, achado num check-up de rotina com leucócitos bem altos (37.000), a maioria linfócitos (70%) — mesmo sem sintomas ou alterações no exame físico, esse padrão de linfocitose isolada num idoso é o quadro clássico de leucemia linfocítica crônica, descoberta bem no início.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352556","ankiGuid":"G^a7[Q)y@~"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-5591703a152fbcd6","number":"1075i","sourceNumber":"1075i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Homem, 70 anos, previamente hígido, assintomático, em avaliação de rotina, apresenta o seguinte hemograma: Hemoglobina = 13,0 g/dl; Hematócrito = 42%; Leucócitos = 78.000/mm³ (segmentados = 12%, linfócitos = 81%; eosinófilos = 1%; monócitos = 6%); plaquetas = 145.000/mm³. Este quadro sugere o diagnóstico de:","options":{"A":"Leucemia Mieloide Crônica","B":"Leucemia Mieloide Aguda","C":"Leucemia Linfocítica Crônica","D":"Leucemia Linfóide Aguda","E":"Linfoma Não Hodgkin Leucemizado"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Idoso sem sintomas, com leucócitos bem altos (78.000) e a grande maioria linfócitos (81%) — quadro clássico de leucemia linfocítica crônica, mesmo sem sintomas ou achados no exame físico.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352557","ankiGuid":"tZk@b|yS]z"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-d75c7eb74e655136","number":"1076i","sourceNumber":"1076i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Paciente masculino, 68 anos, sem comorbidades significativas, apresenta achado de exame físico de esplenomegalia (6 cm abaixo do RCE). Seu hemograma mostra: Hb 14 g%, Leucócitos 78.000/mm³ (Blastos 2%, promielócitos 3%, mielócitos 7%, meta 8%, bastões 10%, segmentados 45%, eosino 3%, baso 5%, linfo 15%, mono 2%), Plaquetas: 850.000/mm³. Qual a conduta adequada ao caso?","options":{"A":"Solicitar recoleta, pois o quadro clínico não é compatível com o exame","B":"Encaminhar o paciente ao Pronto-Socorro, pois se trata de reação leucemoide","C":"Solicitar pesquisa do gene de fusão BCR abl por PCR em sangue periférico","D":"Solicitar Cariótipo com Banda G de sangue periférico","E":"Indicar tratamento imediato com mesilato de imatinibe"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Idoso com baço aumentado e leucócitos bem altos (78.000) mostrando todas as fases de maturação das células mieloides, com plaquetas bem elevadas (850.000) — quadro clássico de leucemia mieloide crônica. O próximo passo é confirmar com a pesquisa do gene de fusão BCR-ABL por PCR, um exame rápido e feito direto no sangue periférico.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352558","ankiGuid":"j[+Veji{aF"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-c8402d1b43e1af10","number":"1077i","sourceNumber":"1077i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Mulher de 47 anos apresenta-se para exame admissional, sem passado mórbido de importância. Ao exame físico, seu baço foi palpado a cerca de 4 cm abaixo do rebordo costal esquerdo, sem outras alterações. Trouxe consigo um hemograma recente com alterações muito sugestivas de leucemia mieloide crônica. Assinale a alternativa com as alterações no hemograma MAIS prováveis para esse diagnóstico:","options":{"A":"Leucocitose, eosinopenia, linfopenia, presença de eritroblastos e de plaquetas gigantes","B":"Leucocitose, trombocitose, basofilia e presença de todos os tipos celulares da linhagem neutrofílica, sem atipias","C":"Leucopenia, anemia, trombocitopenia e presença de neutrófilos hipersegmentados","D":"Leucopenia, linfopenia, anemia e presença de mieloblastos"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Na leucemia mieloide crônica, o hemograma costuma mostrar leucócitos bem altos, plaquetas altas (trombocitose), basófilos aumentados, e a presença de TODAS as fases de maturação das células da linhagem neutrofílica (do mais jovem ao mais maduro), sem sinais de célula anormal (atipia) — um espectro completo e 'ordenado', diferente do que se veria numa leucemia aguda (onde predominam só as células mais jovens, os blastos).","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352559","ankiGuid":"q&SE$o1#Se"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-773c3be46212a145","number":"1078i","sourceNumber":"1078i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Um paciente de 65 anos evolui há 2 meses com astenia, cansaço, tontura, cefaleia, epistaxe. E no último mês necessitou de internação por uma pneumonia. Nos exames laboratoriais apresenta pancitopenia com uma hemoglobina 6,0 g/dl e VCM 110, neutrófilos 450 mm³ e plaquetas 40.000/mm³ e ainda escórias nitrogenadas; ácido úrico; vitamina B12; ácido fólico e sorologias normais. A LDH de 540 U/L. O aspirado de medula revelou uma medula óssea hipercelular para a idade, com 10% de displasia nas séries eritroide e granulocítica e 5% de blastos. A citogenética foi 46, XX [20]. O diagnóstico mais provável é:","options":{"A":"Leucemia aguda","B":"Aplasia de medula","C":"Pancitopenia a esclarecer","D":"Síndrome mielodisplásica"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Cansaço, tontura, dor de cabeça, sangramento de nariz, pneumonia recente, pancitopenia com hemácias grandes (VCM 110), exames de B12/folato/renais normais (descartando essas causas), e a medula mostrando hipercelularidade com displasia (células com formato anormal) em duas linhagens e alguns blastos, mas cariótipo normal — esse padrão preenche os critérios pra síndrome mielodisplásica, uma doença em que a medula 'envelhece' e passa a produzir células defeituosas.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352560","ankiGuid":"M:TDI1b8W="},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-d0a8f6c1736398a2","number":"1079i","sourceNumber":"1079i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"A apresentação clínica inicial na maioria dos pacientes com linfomas não Hodgkin se caracteriza por:","options":{"A":"Linfadenopatia periférica indolor","B":"Anemia hemolítica autoimune","C":"Perda ponderal acelerada","D":"Sudorese noturna profusa","E":"Pancitopenia febril"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"A forma mais comum de o linfoma não Hodgkin aparecer pela primeira vez é com um gânglio aumentado, sem dor — geralmente é esse achado simples que leva o paciente a procurar atendimento médico antes de qualquer outro sintoma mais grave.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352561","ankiGuid":"L(~vv`^JVp"},{"id":"anki-hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes-9e26e165dbf692ab","number":"1080i","sourceNumber":"1080i","collectionBlock":"anki:hematologia-leucemias-cronicas-linfomas-mielodisplasias-e-mieloproliferacoes","collectionLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","subtopic":"","stem":"Qual colagenose mais classicamente associada ao desenvolvimento de linfoma não Hodgkin?","options":{"A":"Esclerodermia","B":"Lúpus eritematoso sistêmico","C":"Doença mista do tecido conjuntivo","D":"Artrite reumatoide","E":"Síndrome de Sjögren"},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","images":[],"optionImages":{},"commentImages":[],"comment":"Entre as doenças do tecido conjuntivo (colagenoses), a síndrome de Sjögren é a mais classicamente associada ao desenvolvimento de linfoma não Hodgkin, principalmente por causa da inflamação crônica das glândulas salivares que pode evoluir pra um linfoma do tipo MALT.","tags":["Hematologia","Leucemias Crônicas Linfomas Mielodisplasias e Mieloproliferações","Anki"],"ankiNoteId":"1742516352562","ankiGuid":"rlGe}=;Wg|"}]};
